CREATE TABLE warehouses(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
INSERT INTO warehouses VALUES('00000000-0000-4000-8000-000000000001','MAIN','المخزن الرئيسي');
CREATE TABLE users(id uuid PRIMARY KEY, username text NOT NULL, username_normalized text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_roles(user_id uuid REFERENCES users ON DELETE RESTRICT, role text CHECK(role IN ('SALES_REP','SALES_MANAGER','WAREHOUSE_MANAGER','FINANCE','LOGISTICS','DRIVER','SUPER_ADMIN')), PRIMARY KEY(user_id,role));
CREATE TABLE sessions(id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),idle_expires_at timestamptz NOT NULL,absolute_expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_limits(key text PRIMARY KEY, started_at timestamptz NOT NULL, attempts integer NOT NULL);
CREATE TABLE customers(id uuid PRIMARY KEY, code text NOT NULL, code_normalized text UNIQUE NOT NULL, name text NOT NULL, phone text NOT NULL, default_address text NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE products(id uuid PRIMARY KEY, sku text NOT NULL, sku_normalized text UNIQUE NOT NULL, name text NOT NULL, unit text NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE orders(id uuid PRIMARY KEY, order_number text UNIQUE, created_by uuid NOT NULL REFERENCES users ON DELETE RESTRICT,customer_id uuid REFERENCES customers ON DELETE RESTRICT,status text NOT NULL CHECK(status IN ('DRAFT','PENDING_APPROVAL','MANAGER_APPROVED','WAREHOUSE_CONFIRMED','IN_TRANSIT','DELIVERED','REJECTED','CANCELLED')),approval_outcome text CHECK(approval_outcome IN ('FULL','PARTIAL','NONE')),customer_snapshot jsonb,creator_name_snapshot text NOT NULL,delivery_address text NOT NULL DEFAULT '',requested_delivery_date date,notes text,fulfillment_issue jsonb,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,manager_approved_at timestamptz,warehouse_confirmed_at timestamptz,dispatched_at timestamptz,delivered_at timestamptz,cancelled_at timestamptz);
CREATE INDEX orders_stage ON orders(status,submitted_at,id);
CREATE INDEX orders_owner ON orders(created_by,submitted_at,id);
CREATE TABLE order_items(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products ON DELETE RESTRICT,product_snapshot jsonb NOT NULL,requested_quantity integer NOT NULL CHECK(requested_quantity>0),approval_status text NOT NULL DEFAULT 'PENDING',approved_quantity integer,rejection_reason text,note text,UNIQUE(order_id,product_id),CHECK((approval_status='PENDING' AND approved_quantity IS NULL) OR (approval_status='APPROVED' AND approved_quantity=requested_quantity) OR (approval_status='REJECTED' AND approved_quantity=0 AND length(trim(rejection_reason))>0)));
CREATE TABLE order_assignments(order_id uuid PRIMARY KEY REFERENCES orders ON DELETE RESTRICT,driver_id uuid NOT NULL REFERENCES users ON DELETE RESTRICT,driver_name_snapshot text NOT NULL,assigned_by uuid NOT NULL REFERENCES users,assigned_at timestamptz NOT NULL DEFAULT now(),scheduled_date date,loading_note text);
CREATE INDEX assignment_driver ON order_assignments(driver_id);
CREATE TABLE inventory_balances(warehouse_id uuid NOT NULL REFERENCES warehouses,product_id uuid NOT NULL REFERENCES products,on_hand integer NOT NULL DEFAULT 0,reserved integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,PRIMARY KEY(warehouse_id,product_id),CHECK(on_hand>=0 AND reserved>=0 AND reserved<=on_hand));
CREATE TABLE reservations(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders,order_item_id uuid UNIQUE NOT NULL REFERENCES order_items,warehouse_id uuid NOT NULL REFERENCES warehouses,product_id uuid NOT NULL REFERENCES products,quantity integer NOT NULL CHECK(quantity>0),state text NOT NULL CHECK(state IN ('ACTIVE','RELEASED','CONSUMED')));
CREATE TABLE stock_movements(id uuid PRIMARY KEY,warehouse_id uuid NOT NULL REFERENCES warehouses,product_id uuid NOT NULL REFERENCES products,order_id uuid REFERENCES orders,type text NOT NULL CHECK(type IN ('OPENING','RECEIPT','ADJUSTMENT','RESERVE','RELEASE','DISPATCH')),on_hand_delta integer NOT NULL,reserved_delta integer NOT NULL,reason text NOT NULL CHECK(length(trim(reason))>0),actor_id uuid NOT NULL REFERENCES users,occurred_at timestamptz NOT NULL DEFAULT now(),operation_id uuid NOT NULL,before_balance jsonb NOT NULL,after_balance jsonb NOT NULL,UNIQUE(operation_id,product_id,type));
CREATE UNIQUE INDEX one_opening ON stock_movements(warehouse_id,product_id) WHERE type='OPENING';
CREATE INDEX movement_product ON stock_movements(product_id,occurred_at,id);
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders,actor_id uuid NOT NULL REFERENCES users,outcome text NOT NULL CHECK(outcome IN ('FAILED','DELIVERED')),reason_code text,reason text,recipient_name text,note text,occurred_at timestamptz NOT NULL DEFAULT now(),CHECK(outcome!='DELIVERED' OR length(trim(recipient_name))>0));
CREATE UNIQUE INDEX one_success ON delivery_attempts(order_id) WHERE outcome='DELIVERED';
CREATE TABLE activity_events(id uuid PRIMARY KEY,order_id uuid REFERENCES orders ON DELETE SET NULL,actor_id uuid REFERENCES users,actor_name_snapshot text NOT NULL,actor_role text NOT NULL,type text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),summary text NOT NULL,changes text,request_id uuid NOT NULL);
CREATE INDEX activity_order ON activity_events(order_id,occurred_at,id);
CREATE TABLE idempotency_records(actor_id uuid NOT NULL REFERENCES users,key text NOT NULL,command text NOT NULL,resource_id uuid,request_hash text NOT NULL,response_status integer NOT NULL,response_body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',PRIMARY KEY(actor_id,key));
CREATE TABLE order_number_counters(year integer PRIMARY KEY,next_value integer NOT NULL);
